public Payment getPaymentDetails(final String paymentLinkId) {
    final PaymentLink paymentLink = paymentLinkDao.findByExternalId(paymentLinkId);
    if (paymentLink.isActive() && paymentLink.isValid()) {
        return paymentService.findByCustomerPaymentId(paymentLink.getCustomerPaymentId());
    }
    paymentLinkDao.expireLink(paymentLink.getCustomerPaymentId());
    throw HalodocWebException.builder().statusCode(400).code(ErrorCode.PAYMNET_LINK_EXPIRED.getCode()).message("Payment link expired")
                             .header("link expired").build();
}
